function chromaticMarkup(){return projectFrame('Digital art / 01','Chromatic Fossils','Excavate something that looks like it came out of a place with different geology. The materials are not trying to look natural.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas chromatic-canvas" aria-label="Generated chromatic geological artwork"></canvas><div class="canvas-overlay"><span>PLATE / <b data-plate-number>001</b></span><span>FOUND COLOR / MATERIAL STUDY</span></div></div><div class="tool-button-row">${action('Excavate another plate','fossil-new',true)}${action('Use a stranger material','fossil-weird')}${action('↓ Export plate','fossil-export')}</div>`,panel('Material lab',select('Material','fossil-palette',[['mineral','Mineral strata'],['bruise','Bruised glass'],['dusk','Twilight sediment'],['sterile','Pale ceramic'],['deep','Deep ocean'],['ultraviolet','Ultraviolet ore'],['toxic','Toxic bloom'],['infrared','Heat scar'],['archive','Archive dust'],['abyss','Abyssal glass'],['oxidized','Oxidized copper'],['fever','Fever mineral'],['sediment','Red sediment'],['petroleum','Petroleum opal'],['biolume','Bioluminescent resin'],['meatglass','Meat glass'],['radioactive','Radioactive enamel'],['void','Void ceramic'],['bone','Iridescent bone'],['rustbloom','Rust bloom'],['oilrainbow','Oil-slick interference']])+range('Layer count','layers',4,48,22)+range('Pressure','pressure',0,150,106,'%')+range('Grain','grain',0,100,54,'%')+range('Fracture','fossil-fracture',0,100,66,'%')+range('Gloss','fossil-gloss',0,100,74,'%')+`<p class="tool-small">The same seed keeps the material layout stable while the controls change its surface and pressure.</p>`),'Original procedural art. The material names are imaginary; the surface behavior is the fun part.');}

