      const bands=[];for(let i=0;i<layers;i++){const base=(i+.4)/layers*h,amp=(9+pressure*68)*(1+fracture*.65),phase=r()*Math.PI*2,shift=(r()-.5)*h*.12,thick=h/layers*(.35+r()*.9);bands.push({base,amp,phase,shift,thick,col:p[Math.floor(r()*p.length)],op:.28+r()*.62});}
