        if(fracture>.08&&i%Math.max(1,Math.floor(4-fracture*3))===0){ctx.save();ctx.globalAlpha=fracture*.8;ctx.strokeStyle=p[(i+2)%p.length];ctx.lineWidth=.7+fracture*2;ctx.beginPath();let x=r()*w,y=b.base+b.shift;ctx.moveTo(x,y);for(let k=0;k<5;k++){x+= (r()-.5)*w*.12;y+=(r()-.5)*h*.13;ctx.lineTo(x,y);}ctx.stroke();ctx.restore();}
