      const palettesByMode={overcast:['#303a49','#8b7d8c','#d3aa92'],electric:['#101a32','#425b83','#b2c9e7'],dry:['#202a38','#5b657b','#e0ac74'],snow:['#344353','#9b9eaa','#e6b9ad'],eclipse:['#080d18','#302945','#b49bad'],glass:['#263b43','#8bb0a9','#d6d5c1']},p=palettesByMode[mode]||palettesByMode.overcast;
      if(mode==='electric'&&!initial){boltClock-=dt||0;if(boltClock<=0){const count=1+Math.floor(Math.random()*2)+(pressure>.66&&Math.random()<.55?1:0);for(let i=0;i<count;i++)bolts.push(makeBolt());boltClock=rand(.16,.48)*(1.12-pressure*.46)*(1.12-light*.2);}bolts.forEach(b=>b.life-=dt||0);bolts=bolts.filter(b=>b.life>0);}
      else if(mode!=='electric'){bolts=[];boltClock=.35;}
      const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,p[0]);g.addColorStop(.58,p[1]);g.addColorStop(1,p[2]);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
      const glow=ctx.createRadialGradient(w*(.25+light*.5),h*(.16+pressure*.2),2,w*(.25+light*.5),h*(.16+pressure*.2),w*.55);glow.addColorStop(0,mode==='eclipse'?'rgba(18,13,25,.9)':mode==='electric'?'rgba(142,188,255,.22)':'rgba(242,200,160,.26)');glow.addColorStop(1,'rgba(10,13,24,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
      clouds.forEach((cl,i)=>{const x=((cl.x*w+time*(wind*11+1.2)*((i%3)+1))%(w+240))-120,y=cl.y*h;ctx.save();ctx.translate(x,y);ctx.scale(cl.scale*1.7,cl.scale*.64);ctx.fillStyle=mode==='snow'?'rgba(230,238,240,.18)':mode==='electric'?`rgba(9,13,25,${.18+pressure*.32})`:`rgba(20,22,34,${cl.alpha+pressure*.13})`;ctx.beginPath();ctx.ellipse(-28,0,54,22,0,0,Math.PI*2);ctx.ellipse(8,-12,48,30,0,0,Math.PI*2);ctx.ellipse(44,2,49,20,0,0,Math.PI*2);ctx.fill();ctx.restore();});
      const horizon=h*hor;for(let layer=0;layer<4;layer++){ctx.beginPath();ctx.moveTo(0,h);const base=horizon+layer*32;for(let x=0;x<=w+8;x+=8){const y=base+Math.sin(x*.008+layer*1.9+seed*.01)*18+Math.sin(x*.021+layer*.8)*7;ctx.lineTo(x,y);}ctx.lineTo(w,h);ctx.closePath();ctx.fillStyle=['rgba(14,20,29,.22)','rgba(16,23,31,.38)','rgba(13,18,26,.62)','rgba(9,13,19,.88)'][layer];ctx.fill();}
      if(mode==='electric'){
        // Charged rain: hundreds of fast, wind-slanted streaks below the storm shelf.
        ctx.save();ctx.strokeStyle='rgba(175,211,255,.48)';ctx.lineWidth=1;
        for(let i=0;i<125;i++){const x=((i*83.7+Math.sin(time*1.7+i*.4)*22+time*(wind*95+18))%(w+35))-15,y=((i*47.3+time*(230+(i%7)*29))%(Math.max(80,horizon*h*.98))),len=5+(i%5)*2;ctx.globalAlpha=.16+(i%6)*.075;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-wind*12,y+len);ctx.stroke();}ctx.globalAlpha=1;
        // Each discharge is a jagged stepped leader with branching side channels.
        bolts.forEach(b=>{const pulse=clamp(b.life/b.duration,0,1),flicker=(Math.sin(time*92+b.flash*17)>.24?1:.42)*pulse;ctx.save();ctx.globalAlpha=flicker; b.branches.forEach(branch=>{drawBoltPath(ctx,branch,w,h,6,'rgba(107,166,255,.16)',17);drawBoltPath(ctx,branch,w,h,1.7,'rgba(175,217,255,.9)',7);});drawBoltPath(ctx,b.points,w,h,13,'rgba(102,150,255,.2)',28);drawBoltPath(ctx,b.points,w,h,5,'rgba(112,182,255,.75)',15);drawBoltPath(ctx,b.points,w,h,2.15,'#f3f8ff',8);ctx.restore();});
        if(bolts.some(b=>b.life/b.duration>.78)){ctx.fillStyle='rgba(176,205,255,.045)';ctx.fillRect(0,0,w,h);}
      }
      if(mode==='snow'||mode==='glass'){for(let i=0;i<75;i++){const x=(i*137.5+time*(wind*25+4))%(w+20),y=(i*79.3+time*(8+(i%5)*3))%(h*.78);ctx.fillStyle=mode==='snow'?'rgba(240,239,232,.48)':'rgba(194,235,232,.32)';ctx.beginPath();ctx.arc(x,y,mode==='snow'?1.5:2.2,0,Math.PI*2);ctx.fill();}}
      if(mode==='eclipse'){ctx.fillStyle='rgba(7,9,17,.92)';ctx.beginPath();ctx.arc(w*.74,h*.23,54,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(182,153,168,.22)';ctx.beginPath();ctx.arc(w*.74-14,h*.23-6,48,0,Math.PI*2);ctx.fill();}
